//! The local socket identity sent to peers.

use std::fmt;

use crate::Frame;

/// The identity this socket announces to its peers (ZMTP `Identity`).
///
/// At most 255 octets, of any value, as libzmq's `ZMQ_ROUTING_ID`. RFC 37
/// reserves a first octet of `0x00` for identities generated by the
/// receiving peer, which libzmq does not enforce, so neither is it here.
/// An empty identity is none: a ROUTER then generates one.
#[derive(Debug, Clone, Default, PartialEq, Eq, Hash)]
pub struct Identity(Frame);

/// Why an [`Identity`] was rejected.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum InvalidIdentity {
    /// Longer than 255 octets.
    TooLong,
}

/// The most octets in an identity, as libzmq limits a routing id.
pub(crate) const MAX_IDENTITY: usize = u8::MAX as usize;

impl Identity {
    /// Validates `identity`.
    pub fn new(identity: impl Into<Frame>) -> Result<Self, InvalidIdentity> {
        let identity = identity.into();
        if identity.len() > MAX_IDENTITY {
            Err(InvalidIdentity::TooLong)
        } else {
            Ok(Self(identity))
        }
    }

    /// The identity octets.
    pub fn as_bytes(&self) -> &[u8] {
        &self.0
    }
}

impl fmt::Display for InvalidIdentity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Self::TooLong => "identity is longer than 255 octets",
        })
    }
}

impl std::error::Error for InvalidIdentity {}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_identity_is_valid() {
        assert_eq!(Identity::new(Frame::new()).unwrap().as_bytes(), b"");
    }

    #[test]
    fn up_to_255_octets_is_valid() {
        let id = Identity::new(vec![b'a'; 255]).unwrap();
        assert_eq!(id.as_bytes().len(), 255);
    }

    #[test]
    fn longer_than_255_octets_is_rejected() {
        assert_eq!(
            Identity::new(vec![b'a'; 256]),
            Err(InvalidIdentity::TooLong)
        );
    }

    #[test]
    fn a_leading_zero_octet_is_valid() {
        let id = Identity::new(&b"\x00abc"[..]).unwrap();
        assert_eq!(id.as_bytes(), b"\x00abc");
    }
}
